package com.nook.widgets;

import android.graphics.*;
import org.json.JSONObject;

/** Small native artwork treatments, without fetching remote images. */
public final class MusicArt {
    private MusicArt(){}
    public static int mix(int first,int second,float amount){return Color.rgb(Math.round(Color.red(first)*(1-amount)+Color.red(second)*amount),Math.round(Color.green(first)*(1-amount)+Color.green(second)*amount),Math.round(Color.blue(first)*(1-amount)+Color.blue(second)*amount));}
    public static int contrast(int background){return Color.luminance(background)>.179?0xff101319:0xfffafbff;}
    public static int dominant(Bitmap source,int fallback){if(source==null)return fallback;Bitmap original=source;if(source.getConfig()==Bitmap.Config.HARDWARE)source=source.copy(Bitmap.Config.ARGB_8888,false);long red=0,green=0,blue=0;int count=0;for(int y=0;y<source.getHeight();y+=Math.max(1,source.getHeight()/20))for(int x=0;x<source.getWidth();x+=Math.max(1,source.getWidth()/20)){int color=source.getPixel(x,y);if(Color.alpha(color)<128)continue;red+=Color.red(color);green+=Color.green(color);blue+=Color.blue(color);count++;}int result=count==0?fallback:Color.rgb((int)(red/count),(int)(green/count),(int)(blue/count));if(source!=original)source.recycle();return result;}
    public static Bitmap artwork(Bitmap source,JSONObject config,int edge,int color,boolean vinyl){
        Bitmap original=source;if(source!=null&&source.getConfig()==Bitmap.Config.HARDWARE)source=source.copy(Bitmap.Config.ARGB_8888,false);Bitmap result=Bitmap.createBitmap(edge,edge,Bitmap.Config.ARGB_8888);result.setDensity(Bitmap.DENSITY_NONE);Canvas canvas=new Canvas(result);Paint paint=new Paint(3);int shape=config.optInt("musicArtShape",0);boolean circle=shape==1||shape==0&&WidgetDesign.id(config)==4||vinyl;float radius=circle?edge/2f:shape==2?0:edge*.15f;Path clip=new Path();clip.addRoundRect(new RectF(0,0,edge,edge),radius,radius,Path.Direction.CW);canvas.save();canvas.clipPath(clip);
        if(vinyl){paint.setColor(0xff15171c);canvas.drawCircle(edge/2f,edge/2f,edge/2f,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Math.max(1,edge/200f));paint.setColor(0xff303238);for(int n=0;n<14;n++)canvas.drawCircle(edge/2f,edge/2f,edge*(.25f+n*.016f),paint);paint.setStyle(Paint.Style.FILL);canvas.save();canvas.scale(.46f,.46f,edge/2f,edge/2f);}
        if(source!=null){float scale=Math.max(edge/(float)source.getWidth(),edge/(float)source.getHeight()),w=source.getWidth()*scale,h=source.getHeight()*scale;canvas.drawBitmap(source,null,new RectF((edge-w)/2,(edge-h)/2,(edge+w)/2,(edge+h)/2),paint);}else{paint.setShader(new LinearGradient(0,0,edge,edge,new int[]{mix(color,Color.WHITE,.3f),mix(color,Color.BLACK,.2f)},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,edge,edge,paint);paint.setShader(null);paint.setColor(contrast(color));paint.setStrokeWidth(edge*.055f);paint.setStyle(Paint.Style.STROKE);canvas.drawLine(edge*.56f,edge*.28f,edge*.56f,edge*.65f,paint);canvas.drawLine(edge*.56f,edge*.28f,edge*.75f,edge*.24f,paint);paint.setStyle(Paint.Style.FILL);canvas.drawOval(edge*.31f,edge*.59f,edge*.59f,edge*.77f,paint);}
        if(vinyl){canvas.restore();paint.setColor(0xff080a0e);canvas.drawCircle(edge/2f,edge/2f,edge*.035f,paint);}canvas.restore();if(source!=original)source.recycle();return result;
    }
    public static Bitmap progress(long position,long duration,int accent,int muted){Bitmap bitmap=Bitmap.createBitmap(320,6,Bitmap.Config.ARGB_8888);bitmap.setDensity(Bitmap.DENSITY_NONE);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);paint.setColor((muted&0xffffff)|0x44000000);canvas.drawRoundRect(0,0,320,6,3,3,paint);paint.setColor(accent);if(duration>0)canvas.drawRoundRect(0,0,Math.max(0,Math.min(320,320f*position/duration)),6,3,3,paint);return bitmap;}
    public static Bitmap cover(Bitmap source,JSONObject config,int width,int height,int color,float radius,boolean shade){
        Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);bitmap.setDensity(Bitmap.DENSITY_NONE);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);Path path=new Path();path.addRoundRect(new RectF(0,0,width,height),radius,radius,Path.Direction.CW);canvas.clipPath(path);
        if(shade){paint.setShader(new LinearGradient(0,0,0,height,new int[]{0x30080b10,0xa0080b10,0xf5080b10},null,Shader.TileMode.CLAMP));canvas.drawRect(0,0,width,height,paint);}else{JSONObject square;try{square=new JSONObject(config.toString()).put("musicArtShape",2);}catch(Exception e){square=config;}Bitmap art=artwork(source,square,320,color,false);float scale=Math.max(width/(float)art.getWidth(),height/(float)art.getHeight()),w=art.getWidth()*scale,h=art.getHeight()*scale;canvas.drawBitmap(art,null,new RectF((width-w)/2,(height-h)/2,(width+w)/2,(height+h)/2),paint);art.recycle();}return bitmap;
    }
    public static Bitmap skip(int seconds,int color){Bitmap bitmap=Bitmap.createBitmap(48,48,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint paint=new Paint(3);paint.setColor(color);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2.5f);boolean back=seconds<0;canvas.save();if(back)canvas.scale(-1,1,24,24);canvas.drawArc(7,7,41,41,290,290,false,paint);Path arrow=new Path();arrow.moveTo(32,3);arrow.lineTo(38,10);arrow.lineTo(29,12);canvas.drawPath(arrow,paint);canvas.restore();paint.setStyle(Paint.Style.FILL);paint.setTypeface(Typeface.create("sans-serif-medium",0));paint.setTextAlign(Paint.Align.CENTER);paint.setTextSize(16);canvas.drawText(String.valueOf(Math.abs(seconds)),24,30,paint);return bitmap;}
}
